588	/// Resolves location links during compilation.
589	///
590	/// This is used in HTML export as there isn't a dedicated export stage that
591	/// could make use of the [`LateLinkResolver`]. There is the HTML serialization,
592	/// but that's not an appropriate stage for meaningful DOM manipulation.
593	pub struct EarlyLinkResolver {
594	    base: Location,
595	    span: Span,
596	}
597	
598	impl EarlyLinkResolver {
599	    /// Creates a resolver that resolves links relatively to the element with
600	    /// the given location.
601	    pub fn new(base: Location, span: Span) -> Self {
602	        Self { base, span }
603	    }
604	
605	    /// Resolves a link to the given location.
606	    pub fn resolve(
607	        &self,
608	        engine: &mut Engine,
609	        location: Location,
610	    ) -> StrResult<ResolvedLink> {
611	        let from = engine.introspect(PathIntrospection(self.base, self.span));
612	        let to = engine.introspect(PathIntrospection(location, self.span));
613	        let anchor = engine
614	            .introspect(LinkAnchorIntrospection(location, self.span))
615	            .ok_or("failed to determine link anchor")?;
616	
617	        Ok(match (from, to) {
618	            // This is the normal case in single file export.
619	            (None, None) => ResolvedLink::Local { anchor },
620	            // This is the normal case in bundle export.
621	            (Some(from), Some(to)) => {
622	                if from == to {
623	                    ResolvedLink::Local { anchor }
624	                } else {
625	                    ResolvedLink::Cross { from, to, anchor }
626	                }
627	            }
628	            // This can, for instance, happen when trying to link to
629	            // metadata that is not within a document (top-level in the
630	            // bundle).
631	            (Some(_), None) => {
632	                bail!("link destination is not within a document")
633	            }
634	            // This is rather unlikely because we can't resolve a link rule
635	            // in a non-file. It could happen in a non-convergent case.
636	            (None, Some(_)) => bail!("failed to resolve cross-link"),
637	        })
638	    }
639	}
640	
641	/// Resolves location links during export.
642	///
643	/// This is used in paged exports. Compared to the [`EarlyLinkResolver`], this
644	/// one can save an introspection iteration as links don't need to be fully
645	/// resolved during compilation. Keeping the location link unresolved will also
646	/// be useful for tagging links in PDF 2.0 (linking to an element and not just a
647	/// position).
648	///
649	/// The downside is that links could be silently broken in a non-converging
650	/// scenario where HTML would instead generate an error, so it's a bit of a
651	/// trade-off and not entirely clear whether this is the best way to do it.
652	pub struct LateLinkResolver<'a> {
653	    base: Option<&'a VirtualPath>,
654	    introspector: &'a dyn Introspector,
655	}
656	
657	impl<'a> LateLinkResolver<'a> {
658	    /// Creates a resolver.
659	    ///
660	    /// - In single-document export, `base` should be `None`.
661	    /// - In bundle export, `base` should be the path of the document relative
662	    ///   to which links shall be resolved.
663	    pub fn new(
664	        base: Option<&'a VirtualPath>,
665	        introspector: &'a dyn Introspector,
666	    ) -> Self {
667	        Self { base, introspector }
668	    }
669	}
670	
671	/// Resolves a link to the given location.
672	#[comemo::track]
673	#[expect(clippy::elidable_lifetime_names, reason = "required for `comemo::track`")]
674	impl<'a> LateLinkResolver<'a> {
675	    pub fn resolve(&self, location: Location) -> Option<ResolvedLink> {
676	        let from = self.base;
677	        let to = self.introspector.path(location);
678	        let anchor = self.introspector.anchor(location)?.clone();
679	
680	        // See `EarlyLinkResolver::resolve` for more details.
681	        Some(match (from, to) {
682	            (None, None) => ResolvedLink::Local { anchor },
683	            (Some(from), Some(to)) => {
684	                if from == to {
685	                    ResolvedLink::Local { anchor }
686	                } else {
687	                    ResolvedLink::Cross { from: from.clone(), to: to.clone(), anchor }
688	                }
689	            }
690	            (Some(_), None) => return None,
691	            (None, Some(_)) => return None,
692	        })
693	    }
694	}
695	
696	/// A resolved internal link.
697	#[derive(Debug, Clone, Eq, PartialEq, Hash)]
698	pub enum ResolvedLink {
699	    /// Should link to an anchor in the same document.
700	    Local {
701	        /// The anchor to link to. If empty, should link to the full current
702	        /// document.
703	        anchor: EcoString,
704	    },
705	    /// Should link to an anchor in another document.
706	    Cross {
707	        /// The path of the file containing the link.
708	        from: VirtualPath,
709	        /// The path of the linked-to file.
710	        to: VirtualPath,
711	        /// The anchor to link to in the `to` file. If empty, should link to the
712	        /// full document.
713	        anchor: EcoString,
714	    },
715	}
716	
717	impl ResolvedLink {
718	    /// Turns the link into a relative URI, potentially with an `#` anchor
719	    /// fragment.
720	    ///
721	    /// This will percent-encode characters in relative paths if necessary.
722	    /// Anchor fragments are guaranteed to be URI-compatible so they are not
723	    /// encoded.
724	    pub fn into_relative_uri(self) -> StrResult<EcoString> {
725	        Ok(match self {
726	            // Still write the empty anchor if linking to the document itself
727	            // because `#` doesn't trigger a reload unlike an empty href.
728	            Self::Local { anchor } => eco_format!("#{anchor}"),
729	            Self::Cross { from, to, anchor } => {
730	                let Some(parent) = from.parent() else {
731	                    // For this to happen, `src` would have to be `/`, which
732	                    // is not allowed.
733	                    bail!("containing document has invalid path");
734	                };
735	
736	                let relative_path = to.relative_from(&parent);
737	                let encoded = percent_encode_path(&relative_path);
738	
739	                if anchor.is_empty() {
740	                    // Don't write a trailing `#` if linking to a full document.
741	                    encoded
742	                } else {
743	                    eco_format!("{encoded}#{anchor}")
744	                }
745	            }
746	        })
747	    }
748	}
749	
750	/// Cross-bundle relative paths may contain characters that are not safe to use
751	/// in URIs. This function encodes them with percent encoding.
752	fn percent_encode_path(relative_path: &str) -> EcoString {
753	    /// This is the complement of an allow-list of alphanumeric + the listed
754	    /// chars. The double negation is necessary because `percent_encode`
755	    /// requires a denylist.
756	    ///
757	    /// Everything not in the allow-list is percent-encoded. What characters in
758	    /// a URI need to be percent-encoded depends a bit on the context (e.g. `?`
759	    /// does not necessarily need to be escaped in all positions). However, we
760	    /// use a very strict allow-list because overcautious encoding only results
761	    /// in less pretty URIs while a missing encoding could result in a broken
762	    /// link.
763	    static NOT_PATH_SAFE: percent_encoding::AsciiSet = percent_encoding::NON_ALPHANUMERIC
764	        // These are all unreserved.
765	        .remove(b'-')
766	        .remove(b'.')
767	        .remove(b'_')
768	        .remove(b'~')
769	        // Slashes should be kept as-is, as they separate fragments in the
770	        // relative path.
771	        .remove(b'/');
772	
773	    // Encode the path with URI encoding.
774	    let encoded_parts =
775	        percent_encoding::percent_encode(relative_path.as_bytes(), &NOT_PATH_SAFE);
776	
777	    // TODO: This loop can be replaced with `collect()` after bumping to ecow 0.3.
778	    let mut encoded = EcoString::new();
779	    for item in encoded_parts {
780	        encoded.push_str(item);
781	    }
782	
783	    encoded
784	}
785	
786	/// Resolves the anchor to reach the linked-to element with the given location.
787	#[derive(Debug, Clone, PartialEq, Hash)]
788	struct LinkAnchorIntrospection(Location, Span);
789	
790	impl Introspect for LinkAnchorIntrospection {
791	    type Output = Option<EcoString>;
792	
793	    fn introspect(
794	        &self,
795	        _: &mut Engine,
796	        introspector: Tracked<dyn Introspector + '_>,
797	    ) -> Self::Output {
798	        introspector.anchor(self.0).cloned()
799	    }
800	
801	    fn diagnose(&self, history: &History<Self::Output>) -> SourceDiagnostic {
802	        let introspector = history.final_introspector();
803	        let what = match introspector.query_first(&Selector::Location(self.0)) {
804	            Some(content) => content.elem().name(),
805	            None => "element",
806	        };
807	        warning!(
808	            self.1,
809	            "link anchor assigned to the destination {what} did not stabilize",
810	        )
811	        .with_hint(history.hint("anchors", |id| match id {
812	            Some(id) => id.clone(),
813	            None => "(no anchor)".into(),
814	        }))
815	    }
816	}
