    fn collect_combined_result<B>(self) -> SourceResult<B>
    where
        B: FromIterator<Self::Item>,
    {
        let mut errors = EcoVec::new();
        let collected = self
            .filter_map(|result| match result {
                Ok(item) => Some(item),
                Err(errs) => {
                    errors.extend(errs);
                    None
                }
            })
            .collect();
        if !errors.is_empty() {
            return Err(errors);
        }
        Ok(collected)
    }
}

